//! Port of Linux `drivers/gpu/drm/drm_edid.c` (batch B1d).
//!
//! Source-faithful transcription of Linux 7.2.3: EDID block validation and
//! the DDC read path, the DMT / established / standard / CEA / DisplayID mode
//! derivation, the CTA data-block iterator and its HDMI, HDR, DSC, VCDB and
//! Y420 parsers, the ELD and SAD helpers, the monitor-range and
//! reduced-blanking helpers, and the AVI/vendor infoframe helpers.
//!
//! Deviations:
//! - `struct drm_edid` is private to the C file; it is mirrored here as
//!   [`DrmEdid`] with the same two fields.
//! - The DDC adapter is the TheKernel `I2cAdapter` Rust object. The
//!   `connector->ddc` pointer is cast to it in [`i2c_transfer`].
//! - The CTA/DisplayID mode tables are generated from the C tables (see the
//!   `TABLES` section at the end of the file); the `struct drm_display_mode`
//!   templates are materialised with [`mode_from_tpl`].
//! - Debug/error output goes through `tk_linux_kapi::print::drm_log_at`
//!   instead of `va_format`.
//! - `drm_edid_load` (CONFIG_DRM_LOAD_EDID_FIRMWARE) is not built on the
//!   x86_64 TheKernel target; it returns `-ENOENT`, as the disabled path does.

#![allow(clippy::missing_safety_doc)]
#![allow(non_upper_case_globals)]
#![allow(dead_code)]
#![allow(unsafe_op_in_unsafe_fn)]

