const DRM_MODE_MATCH_FLAGS: u32 = 1 << 2;
const DRM_MODE_MATCH_ASPECT_RATIO: u32 = 1 << 4;

// upstream: drm_edid.c oui()
#[inline]
fn oui(first: u8, second: u8, third: u8) -> i32 {
    ((first as i32) << 16) | ((second as i32) << 8) | third as i32
}

